bench_run = function(d) {
	drop_highly_correlated_cols_ladder = function(M, thresholds) {
		M = as.matrix(M)
		js = seq_len(ncol(M))
		if (ncol(M) <= 1) return(rep(list(as.numeric(js)), length(thresholds)))
		const_cols = which(apply(M, 2, var) == 0)
		if (length(const_cols) > 0) {
			M = M[, -const_cols, drop = FALSE]
			js = js[-const_cols]
			if (ncol(M) <= 1) return(rep(list(as.numeric(js)), length(thresholds)))
		}
		A = abs(suppressWarnings(stats::cor(M)))
		A[lower.tri(A, diag = TRUE)] = 0
		lapply(thresholds, function(t) {
			j_kill = which(colSums(A > t, na.rm = TRUE) > 0)
			as.numeric(if (length(j_kill)) js[-j_kill] else js)
		})
	}
	drop_highly_correlated_cols_ladder(d$M, d$thresholds)
}
